PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS sources(id INTEGER PRIMARY KEY,path TEXT UNIQUE,checksum TEXT,license TEXT,status TEXT,rows INTEGER DEFAULT 0,imported_at TEXT);
CREATE TABLE IF NOT EXISTS greenhouses(id TEXT PRIMARY KEY,name TEXT NOT NULL,location TEXT,description TEXT);
CREATE TABLE IF NOT EXISTS nodes(id TEXT PRIMARY KEY,greenhouse_id TEXT NOT NULL REFERENCES greenhouses(id),row_index INTEGER,col_index INTEGER);
CREATE TABLE IF NOT EXISTS readings(id INTEGER PRIMARY KEY,source_id INTEGER NOT NULL REFERENCES sources(id),node_id TEXT NOT NULL REFERENCES nodes(id),event_time TEXT NOT NULL,temperature REAL,humidity REAL,rssi REAL,snr REAL,quality TEXT NOT NULL,UNIQUE(source_id,node_id,event_time));
CREATE INDEX IF NOT EXISTS ix_readings_node_time ON readings(node_id,event_time);
CREATE INDEX IF NOT EXISTS ix_readings_time ON readings(event_time);
CREATE TABLE IF NOT EXISTS replay_state(id INTEGER PRIMARY KEY CHECK(id=1),cursor TEXT NOT NULL,speed REAL NOT NULL,running INTEGER NOT NULL DEFAULT 0,transport TEXT NOT NULL,session_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS model_versions(id TEXT PRIMARY KEY,trained_at TEXT,train_end TEXT,val_end TEXT,feature_spec TEXT,metrics TEXT,path TEXT,status TEXT);
CREATE TABLE IF NOT EXISTS predictions(id INTEGER PRIMARY KEY,node_id TEXT REFERENCES nodes(id),model_id TEXT REFERENCES model_versions(id),issued_at TEXT,target_time TEXT,temperature REAL,humidity REAL,vpd REAL,UNIQUE(node_id,model_id,issued_at,target_time));
CREATE TABLE IF NOT EXISTS alerts(id TEXT PRIMARY KEY,session_id TEXT NOT NULL,node_id TEXT NOT NULL REFERENCES nodes(id),type TEXT NOT NULL,severity TEXT,status TEXT NOT NULL,opened_at TEXT,last_seen TEXT,evidence_json TEXT NOT NULL,note TEXT DEFAULT '');
CREATE INDEX IF NOT EXISTS ix_alerts_node_type ON alerts(session_id,node_id,type,status);
CREATE TABLE IF NOT EXISTS commands(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES alerts(id),target TEXT NOT NULL,action TEXT NOT NULL,status TEXT NOT NULL,requested_at TEXT,ack_at TEXT,operator_note TEXT);
CREATE TABLE IF NOT EXISTS command_logs(id INTEGER PRIMARY KEY,command_id TEXT NOT NULL REFERENCES commands(id),state TEXT NOT NULL,created_at TEXT,payload TEXT);
CREATE TABLE IF NOT EXISTS knowledge_documents(id TEXT PRIMARY KEY,title TEXT NOT NULL,url TEXT NOT NULL,license TEXT,text TEXT NOT NULL,checksum TEXT);
CREATE TABLE IF NOT EXISTS knowledge_chunks(id TEXT PRIMARY KEY,document_id TEXT REFERENCES knowledge_documents(id),text TEXT NOT NULL,ordinal INTEGER,metadata TEXT);
CREATE TABLE IF NOT EXISTS chat_messages(id TEXT PRIMARY KEY,session_id TEXT,role TEXT,content TEXT,evidence_json TEXT,provider TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value_json TEXT NOT NULL,updated_at TEXT);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,kind TEXT NOT NULL,status TEXT NOT NULL,progress REAL NOT NULL,message TEXT,result_json TEXT,started_at TEXT,finished_at TEXT);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,display_name TEXT NOT NULL,role TEXT NOT NULL,password_salt TEXT NOT NULL,password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS greenhouse_replay(greenhouse_id TEXT PRIMARY KEY REFERENCES greenhouses(id),cursor TEXT NOT NULL,speed REAL NOT NULL,running INTEGER NOT NULL DEFAULT 0,transport TEXT NOT NULL,session_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS greenhouse_settings(greenhouse_id TEXT NOT NULL REFERENCES greenhouses(id),key TEXT NOT NULL,value_json TEXT NOT NULL,updated_at TEXT,PRIMARY KEY(greenhouse_id,key));
